beforeExample:
import java.text.MessageFormat;

public class MyClass {
    public String getFormattedString(String key, Object arg) {
        return MessageFormat.format(key, new Object[] { arg });
    }

    public String getStatusMessage(String status) {
        String pattern = "Status: {0}";
        return MessageFormat.format(pattern, new Object[] { status });
    }
}

afterExample:
import java.text.MessageFormat;

public class MyClass {
    public String getFormattedString(String key, Object arg) {
        return MessageFormat.format(key, arg);
    }

    public String getStatusMessage(String status) {
        String pattern = "Status: {0}";
        return MessageFormat.format(pattern, status);
    }
}

negativeExample:
import java.text.MessageFormat;

public class MyClass {
    public String formatMultipleArgs(String pattern, Object arg1, Object arg2) {
        // Should not match: multiple arguments require an array or direct varargs
        return MessageFormat.format(pattern, new Object[] { arg1, arg2 });
    }

    public String formatDirectVarargs(String pattern, Object arg) {
        // Should not match: already uses direct varargs
        return MessageFormat.format(pattern, arg);
    }
}
